insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a24ddebd-55fd-46e2-abae-d56dc9e04b5b', 'situacion', 'MICKEY S1 · Pregunta 1', 'ctx-sit', '<p>Una persona compara tres rutas de bus para ir al trabajo.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col"></th><th scope="col">Ruta 1</th><th scope="col">Ruta 2</th><th scope="col">Ruta 3</th></tr></thead><tbody><tr><th scope="row">Número máximo de pasajeros</th><td>30</td><td>20</td><td>60</td></tr><tr><th scope="row">Velocidad (km/h)</th><td>7</td><td>5</td><td>4</td></tr><tr><th scope="row">Tiempo de recorrido (min)</th><td>154</td><td>180</td><td>300</td></tr><tr><th scope="row">Distancia recorrida (km)</th><td>18</td><td>15</td><td>20</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e107ef25-b13d-4f88-958b-c371578c935b', 'situacion', 'MICKEY S1 · Pregunta 2', 'ctx-sit', '<p>En un grupo de 20 estudiantes, la moda de las calificaciones fue Sobresaliente. Al menos uno obtuvo Insuficiente; hubo tantos Excelentes como Insuficientes y ocho Aceptables.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('3ad6e434-9c2e-4cc4-a899-5e7d0ca1251f', 'situacion', 'MICKEY S1 · Pregunta 3', 'ctx-sit', '<p>Se premiará a quien tenga el mejor promedio de los cuatro periodos.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Estudiante</th><th scope="col">Periodo 1</th><th scope="col">Periodo 2</th><th scope="col">Periodo 3</th><th scope="col">Periodo 4</th></tr></thead><tbody><tr><th scope="row">1</th><td>3,5</td><td>3,0</td><td>3,5</td><td>3,0</td></tr><tr><th scope="row">2</th><td>2,5</td><td>3,5</td><td>3,0</td><td>4,5</td></tr><tr><th scope="row">3</th><td>4,5</td><td>2,5</td><td>4,5</td><td>2,5</td></tr><tr><th scope="row">4</th><td>2,5</td><td>5,0</td><td>2,5</td><td>3,0</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('059ed695-a38a-4992-9cdf-a7cc693b2d80', 'situacion', 'MICKEY S1 · Pregunta 4', 'ctx-sit', '<p>Dos magnitudes son directamente proporcionales. Para hallar el faltante se hace: 1. Multiplicar 6×8. 2. Dividir ese resultado entre 8. 3. Simplificar.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Magnitud 1</th><th scope="col">Magnitud 2</th></tr></thead><tbody><tr><th scope="row">4</th><td>8</td></tr><tr><th scope="row">6</th><td>¿?</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('97ea0f83-32b8-4202-b08e-42f9f31e3b50', 'situacion', 'MICKEY S1 · Pregunta 5', 'ctx-sit', '<p>Dos postes paralelos de 10 m y 5 m proyectan sombras bajo la misma iluminación. El ángulo entre la acera y la sombra del primero es de 30°.</p><figure class="ctx-fig"><img src="img/figuras/mat/mi-q05-postes.webp" alt="Postes paralelos de distinta altura con sombras paralelas; ángulo alfa de 30° en el primero y beta en el segundo." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('34d63edc-487c-4a87-bca9-11fc009df3a9', 'situacion', 'MICKEY S1 · Pregunta 6', 'ctx-sit', '<p>Se seleccionará un estudiante entre los hombres del curso. Un profesor dice que la probabilidad de elegir uno de 15 años es 2/5 porque hay dos hombres de esa edad en el curso de cinco estudiantes.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Estudiante</th><th scope="col">1</th><th scope="col">2</th><th scope="col">3</th><th scope="col">4</th><th scope="col">5</th></tr></thead><tbody><tr><th scope="row">Sexo</th><td>H</td><td>M</td><td>H</td><td>H</td><td>M</td></tr><tr><th scope="row">Edad (años)</th><td>15</td><td>17</td><td>17</td><td>15</td><td>15</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('6da26581-c60a-433e-91ad-cd278191d810', 'situacion', 'MICKEY S1 · Pregunta 7', 'ctx-sit', '<p>Se espera una relación lineal creciente entre los días transcurridos desde la publicación de un artículo y el número de citas que recibe.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('3dbde1e6-5621-4edd-8bdb-e28853828157', 'situacion', 'MICKEY S1 · Pregunta 8', 'ctx-sit', '<p>Una persona dispone de 90.000 euros y requiere un automóvil que alcance al menos 110 km/h. Entre los que cumplen busca mayor autonomía.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Marca</th><th scope="col">Autonomía (km)</th><th scope="col">Velocidad máxima (km/h)</th><th scope="col">Precio (euros)</th></tr></thead><tbody><tr><th scope="row">1</th><td>100</td><td>80</td><td>16.400</td></tr><tr><th scope="row">2</th><td>160</td><td>112</td><td>99.000</td></tr><tr><th scope="row">3</th><td>90</td><td>65</td><td>8.500</td></tr><tr><th scope="row">4</th><td>150</td><td>90</td><td>14.500</td></tr><tr><th scope="row">5</th><td>80</td><td>80</td><td>7.400</td></tr><tr><th scope="row">6</th><td>160</td><td>126</td><td>26.900</td></tr><tr><th scope="row">7</th><td>120</td><td>130</td><td>25.000</td></tr><tr><th scope="row">8</th><td>400</td><td>210</td><td>99.000</td></tr><tr><th scope="row">9</th><td>250</td><td>170</td><td>297.000</td></tr><tr><th scope="row">10</th><td>200</td><td>85</td><td>28.000</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e86f0a93-d26b-4083-bd9b-d08fe6adf364', 'situacion', 'MICKEY S1 · Pregunta 9', 'ctx-sit', '<p>Una academia cobra las mensualidades de la tabla. Quien toma dos cursos recibe un 20 % de descuento; quien toma tres o más, un 30 %.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Curso</th><th scope="col">Precio mensual</th></tr></thead><tbody><tr><th scope="row">Guitarra</th><td>$130.000</td></tr><tr><th scope="row">Batería</th><td>$150.000</td></tr><tr><th scope="row">Piano</th><td>$120.000</td></tr><tr><th scope="row">Canto</th><td>$170.000</td></tr></tbody></table></div><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Guitarra</th><th scope="col">Batería</th><th scope="col">Piano</th><th scope="col">Canto</th></tr></thead><tbody><tr><th scope="row">10</th><td>6</td><td>15</td><td>9</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d52df72c-21bd-4723-b01d-ec42b495be42', 'situacion', 'MICKEY S1 · Pregunta 11', 'ctx-sit', '<p>La tabla indica cemento y arena para un metro cúbico de mezcla según su aplicación. Se construirá un muro de 3 m por 2 m por 0,5 m.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Aplicación</th><th scope="col">Cemento (kg)</th><th scope="col">Arena (kg)</th></tr></thead><tbody><tr><th scope="row">Pisos</th><td>35</td><td>70</td></tr><tr><th scope="row">Techos</th><td>30</td><td>90</td></tr><tr><th scope="row">Muros</th><td>25</td><td>75</td></tr><tr><th scope="row">Revestimientos</th><td>20</td><td>100</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d71838d8-9333-4007-ad45-2b867b5f9df5', 'situacion', 'MICKEY S1 · Pregunta 12', 'ctx-sit', '<p>Un granjero calcula el área multiplicando los catetos y dividiendo entre dos.</p><figure class="ctx-fig"><img src="img/figuras/mat/mi-q12-triangulo.webp" alt="Triángulo rectángulo con catetos de 4 m y 3 m e hipotenusa de 5 m." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('498ac2a4-55ae-48cb-969f-effb93aae64e', 'situacion', 'MICKEY S1 · Pregunta 13', 'ctx-sit', '<p>Se pide un número divisible por 2 y por 5 que, al dividirlo entre 4, deje residuo 2. Andrés propone el 40.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ad64a556-9e21-4d52-9c59-a79d68399cd6', 'situacion', 'MICKEY S1 · Pregunta 14', 'ctx-sit', '<p>Una tienda clasifica la vajilla con una, dos o tres estrellas según su calidad.</p><figure class="ctx-fig"><img src="img/figuras/mat/mi-q14-vajilla.webp" alt="Platos redondos: $2.500, $4.000 y $9.000. Platos hondos: $1.500, $4.000 y $4.000. Vasos: $1.000 en las tres calidades." loading="lazy"></figure><p>Un cliente tiene cinco platos redondos, cuatro hondos y tres vasos, todos de dos estrellas. Completa cinco piezas de cada tipo. Al final, el promedio de estrellas es 2 en vasos, 2 en redondos y 2,2 en hondos.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9c18b1c7-935e-4cc7-82a1-456d0233d70f', 'situacion', 'MICKEY S1 · Pregunta 15', 'ctx-sit', '<p>Una tienda clasifica la vajilla con una, dos o tres estrellas según su calidad.</p><figure class="ctx-fig"><img src="img/figuras/mat/mi-q14-vajilla.webp" alt="Platos redondos: $2.500, $4.000 y $9.000. Platos hondos: $1.500, $4.000 y $4.000. Vasos: $1.000 en las tres calidades." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('81c3b0e1-8aad-4c38-9e27-1f44fbc5efe5', 'situacion', 'MICKEY S1 · Pregunta 17', 'ctx-sit', '<p>Jaime destina el 30 % del sueldo a la cuota de su casa. Divide el porcentaje restante en partes iguales para el auto y para gastos generales.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ff3e3ba9-8af7-41a5-be2d-40d5cc4a0c7b', 'situacion', 'MICKEY S1 · Pregunta 18', 'ctx-sit', '<p>Juan recibe 20 hectáreas, Carlos 70 y Camila 50. Camila paga 20 millones. Juan propone dividir ese pago entre 50 y multiplicar por sus hectáreas; Carlos propone 70×20.000.000/50.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('b5c93b30-27cd-4740-8a60-6cdb93eabcaf', 'situacion', 'MICKEY S1 · Pregunta 19', 'ctx-sit', '<p>Una agencia encuestó sobre aplicaciones móviles. La primera gráfica compara edades; la segunda resume únicamente a quienes tienen de 25 a 35 años.</p><figure class="ctx-fig"><img src="img/figuras/mat/mi-q19-barras.webp" alt="Para el grupo de 25 a 35 años: mensajería 35, juegos 20 y redes sociales 45." loading="lazy"></figure><figure class="ctx-fig"><img src="img/figuras/mat/mi-q19-circular.webp" alt="Gráfico circular del grupo 25–35: mensajería 35 %, juegos 20 % y redes sociales 45 %." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('be5f195c-f934-45ad-b256-7325b0b2516c', 'situacion', 'MICKEY S1 · Pregunta 20', 'ctx-sit', '<p>La tabla registra los nacimientos en un municipio durante una semana.</p><figure class="ctx-fig"><img src="img/figuras/mat/mi-q20-nacimientos.webp" alt="Mujeres: lunes 12, martes 13, miércoles 10, jueves 8 y viernes 6; hombres: 7, 10, 19, 18 y 12." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a6543997-7d23-4355-8e92-d67552989ee7', 'situacion', 'MICKEY S1 · Pregunta 21', 'ctx-sit', '<p>Para ajustar una gráfica a los datos se busca la menor suma de distancias entre los valores registrados y los representados. Se proponen una recta y una parábola.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">x</th><th scope="col">y</th></tr></thead><tbody><tr><th scope="row">1</th><td>2</td></tr><tr><th scope="row">2</th><td>4</td></tr><tr><th scope="row">3</th><td>9</td></tr><tr><th scope="row">4</th><td>15</td></tr></tbody></table></div><figure class="ctx-fig"><img src="img/figuras/mat/mi-q21-recta.webp" alt="Recta que pasa por (1,2), (2,6), (3,10) y (4,14)." loading="lazy"></figure><figure class="ctx-fig"><img src="img/figuras/mat/mi-q21-parabola.webp" alt="Parábola con valores (1,1), (2,4), (3,9) y (4,16)." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a0c40ee0-e6df-40ee-938c-4abf35f7b775', 'situacion', 'MICKEY S1 · Pregunta 22', 'ctx-sit', '<p>Una empresa vendió en 2014 todas las unidades de calzado de la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Producto</th><th scope="col">Costo de fabricación</th><th scope="col">Precio de venta</th><th scope="col">Unidades vendidas</th></tr></thead><tbody><tr><th scope="row">Botas</th><td>$30.000</td><td>$32.000</td><td>500</td></tr><tr><th scope="row">Zapatillas</th><td>$25.000</td><td>$30.000</td><td>800</td></tr><tr><th scope="row">Zapatos deportivos</th><td>$35.000</td><td>$35.000</td><td>2.000</td></tr><tr><th scope="row">Zapatos formales</th><td>$50.000</td><td>$60.000</td><td>1.200</td></tr></tbody></table></div><p>Para identificar la mayor inversión se propone: 1. Ordenar los productos por costo de fabricación unitario. 2. Multiplicar costo unitario por unidades de cada producto. 3. Comparar los resultados y escoger el mayor.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('91bbd0aa-184b-4989-9c3e-fa005afd8386', 'situacion', 'MICKEY S1 · Pregunta 23', 'ctx-sit', '<p>Una empresa vendió en 2014 todas las unidades de calzado de la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Producto</th><th scope="col">Costo de fabricación</th><th scope="col">Precio de venta</th><th scope="col">Unidades vendidas</th></tr></thead><tbody><tr><th scope="row">Botas</th><td>$30.000</td><td>$32.000</td><td>500</td></tr><tr><th scope="row">Zapatillas</th><td>$25.000</td><td>$30.000</td><td>800</td></tr><tr><th scope="row">Zapatos deportivos</th><td>$35.000</td><td>$35.000</td><td>2.000</td></tr><tr><th scope="row">Zapatos formales</th><td>$50.000</td><td>$60.000</td><td>1.200</td></tr></tbody></table></div><p>La utilidad neta total es de $17.000.000. Para hallar la participación de un producto se calcula (precio − costo)×unidades, se divide entre la utilidad total y se multiplica por 100.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('61a0d2ac-e576-4ea3-953a-9047b7d4341f', 'situacion', 'MICKEY S1 · Pregunta 24', 'ctx-sit', '<p>Una empresa vendió en 2014 todas las unidades de calzado de la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Producto</th><th scope="col">Costo de fabricación</th><th scope="col">Precio de venta</th><th scope="col">Unidades vendidas</th></tr></thead><tbody><tr><th scope="row">Botas</th><td>$30.000</td><td>$32.000</td><td>500</td></tr><tr><th scope="row">Zapatillas</th><td>$25.000</td><td>$30.000</td><td>800</td></tr><tr><th scope="row">Zapatos deportivos</th><td>$35.000</td><td>$35.000</td><td>2.000</td></tr><tr><th scope="row">Zapatos formales</th><td>$50.000</td><td>$60.000</td><td>1.200</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('83e4f84b-acce-4cd3-b96c-ae7d871e804e', 'situacion', 'MICKEY S1 · Pregunta 26', 'ctx-sit', '<p>La gráfica registra el precio del dólar en pesos colombianos durante varios meses de 2010 a 2012.</p><figure class="ctx-fig"><img src="img/figuras/mat/mi-q26-dolar.webp" alt="Serie temporal del dólar entre aproximadamente $1.700 y $2.000, con dos picos altos durante 2011." loading="lazy"></figure>');
