  array['<div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Calificación</th><th scope="col">Número de estudiantes</th></tr></thead><tbody><tr><th scope="row">Insuficiente</th><td>1</td></tr><tr><th scope="row">Aceptable</th><td>8</td></tr><tr><th scope="row">Sobresaliente</th><td>10</td></tr><tr><th scope="row">Excelente</th><td>1</td></tr></tbody></table></div>', '<div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Calificación</th><th scope="col">Número de estudiantes</th></tr></thead><tbody><tr><th scope="row">Insuficiente</th><td>3</td></tr><tr><th scope="row">Aceptable</th><td>8</td></tr><tr><th scope="row">Sobresaliente</th><td>6</td></tr><tr><th scope="row">Excelente</th><td>3</td></tr></tbody></table></div>', '<div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Calificación</th><th scope="col">Número de estudiantes</th></tr></thead><tbody><tr><th scope="row">Insuficiente</th><td>5</td></tr><tr><th scope="row">Aceptable</th><td>8</td></tr><tr><th scope="row">Sobresaliente</th><td>2</td></tr><tr><th scope="row">Excelente</th><td>5</td></tr></tbody></table></div>', '<div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Calificación</th><th scope="col">Número de estudiantes</th></tr></thead><tbody><tr><th scope="row">Insuficiente</th><td>0</td></tr><tr><th scope="row">Aceptable</th><td>8</td></tr><tr><th scope="row">Sobresaliente</th><td>12</td></tr><tr><th scope="row">Excelente</th><td>0</td></tr></tbody></table></div>'],
  'Comprueba cada condición por separado, incluida la suma total.', 'publicada', 'modelo', '1f1e44d65cd524c61769b78031546773', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c006d87e-499f-4060-b5fe-3f7c215e26d9', 0, 'La distribución 1, 8, 10 y 1 suma 20, tiene una persona con Insuficiente, igual número de Excelentes y su mayor frecuencia es Sobresaliente. Las otras incumplen la moda o la existencia de Insuficientes.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'db8a0172-36c7-4845-83a7-f326da60ef16', 'mat',
