  (select id from public.lotes where codigo = '2026-B'),
  '3ad6e434-9c2e-4cc4-a899-5e7d0ca1251f', 'Estadística descriptiva',
  '¿Quién gana el premio?',
  array['Estudiante 1.', 'Estudiante 2.', 'Estudiante 3.', 'Estudiante 4.'],
  'Cuando todos tienen igual cantidad de notas, puedes comparar sus sumas.', 'publicada', 'modelo', 'd54dd1086a3de63bc5edcd98a2544e7b', 'baja';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('db8a0172-36c7-4845-83a7-f326da60ef16', 2, 'Las sumas son 13; 13,5; 14 y 13. Como todos tienen cuatro notas, la mayor suma también da el mayor promedio: 14/4 = 3,5 para el estudiante 3.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '345b25bd-74a9-450c-9d26-9ee7d826af14', 'mat',
