  array['En el 1; debe multiplicarse 4×8.', 'En el 2; debe dividirse entre 4.', 'En el 1; debe dividirse entre 8.', 'En el 2; debe multiplicarse por 4.'],
  'Conserva la razón entre valores correspondientes.', 'publicada', 'modelo', '96f1fd54dd5a9c3dcc2a04ad250f4c62', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('345b25bd-74a9-450c-9d26-9ee7d826af14', 1, 'La razón entre las magnitudes es 8/4 = 2. El valor buscado es 6×8/4 = 12. La división entre 8 elimina el factor incorrecto.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '73860052-3e1d-4fd5-a6e7-619dbec95079', 'mat',
