insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('73860052-3e1d-4fd5-a6e7-619dbec95079', 2, 'Las sombras se proyectan en la misma dirección y forman ángulos correspondientes iguales con la acera. La diferencia de altura no cambia ese ángulo: β = 30°.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b84ff776-177c-4a13-9eaa-943c30b54b58', 'mat',
