insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('80d1d320-b2f9-4ac3-b3bf-0cf452585073', 3, 'Las marcas 6 y 7 cumplen presupuesto y velocidad. La 6 recorre 160 km, más que los 120 km de la 7. La marca 8 supera el presupuesto y la 10 no alcanza 110 km/h.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
