insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0be9c2d6-c37f-463e-b23d-53ae1a0bd43d', 1, 'El ingreso mínimo ocurre si los diez alumnos reciben el mayor descuento, 30 %. Cada uno paga el 70 % de 130.000 y el total es 10×130.000×0,7 = 910.000.');

