insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b4b4866e-da1a-4ac0-8594-1312a0b35e72', 2, 'El volumen es 3×2×0,5 = 3 m³. La fila de muros exige 25 y 75 kg por m³; para tres se requieren 75 kg de cemento y 225 de arena.');

